entries[409434] = { ["name"] = "Der stille Stern", ["text"] = "Ca. 5 Procs pro Minute\nWenn nahe Verbündete Schaden erleiden, besteht eine Chance, dass die Stimme Euch lockt. Hört Ihr sie 10 Mal, unterwerft Ihr Euch ihrem Einfluss vollständig, stehlt den 4 nächsten Verbündeten 8 ihres niedrigsten Sekundärwerts und erhaltet 8 Sek. lang die gestohlene Menge plus 116 als Bonus auf Euren höchsten Sekundärwert." }
entries[409436] = { ["name"] = "Abendrot und Morgenrot", ["text"] = "Wenn Ihr 3 Fähigkeiten wirkt, die Heilige Kraft erzeugen, erhaltet Ihr 'Segen des Morgens'. Wenn Ihr 'Segen des Morgens' verbraucht, erhaltet Ihr 'Segen des Abends'.\n\nSegen des Morgens\nEuer nächster Einsatz einer Fähigkeit, die Heilige Kraft verbraucht, verursacht 30% mehr Schaden und Heilung. Dieser Effekt ist stapelbar.\n\nSegen des Abends\nErlittener Schaden um 4%$ verringert, ?s385129&c2[ Rüstung um 4% erhöht und Fähigkeiten, die Heilige Kraft erzeugen, klingen 4% schneller ab][] [ Siegel der Ordnung : und Eure Fähigkeiten, die Heilige Kraft erzeugen, gewähren auch 10 Sek. Sek. lang einen Absorptionsschild in Höhe von 4% des Schadens oder der hervorgerufenen Heilung ]", ["unresolvedValues"] = true }
entries[409437] = { ["name"] = "Sengendes Sekret", ["text"] = "100 Meter Reichweite\nWirken in 1.5 sek. 3 sek. Abklingzeit\nVerursacht beim Einschlag 74205 Feuerschaden sowie 10 Sek. lang alle 1 Sek. zusätzlich 23875 Feuerschaden, wenn der Zaubernde sich nicht im Nahkampf befindet." }
entries[409438] = { ["name"] = "Seismischer Schlag", ["text"] = "100 Meter Reichweite\nSofort\nEin 'Erdrutsch' lässt Gegner, die sich in der Luft befinden, zu Boden stürzen und betäubt sie 4 Sek. lang. Zusätzlich ist die Abklingzeit von 'Erdrutsch' um 15 Sek. verringert." }
