entries[409600] = { ["name"] = "Der stille Stern", ["text"] = "Sofort\nWenn nahe Verbündete Schaden erleiden, besteht eine Chance, dass die Stimme Euch lockt. Hört Ihr sie 10 Mal, unterwerft Ihr Euch ihrem Einfluss vollständig, stehlt den 4 nächsten Verbündeten 8 ihres niedrigsten Sekundärwerts und erhaltet 8 Sek. lang die gestohlene Menge plus 116 als Bonus auf Euren höchsten Sekundärwert." }
