entries[409647] = { ["name"] = "Zwillingsflammen", ["text"] = "100 Meter Reichweite\nSofort\nHüllt Gegner in ' Einäschernde Flammen ' oder ' Verderbte Flammen '.\n\nEinäschernde Flammen\nFügt Gegnern innerhalb von 10 Metern 14 Sek. lang alle 1 Sek. 271054 Feuerschaden zu.\n\nBetreten eines Bereichs von ' Verderbte Flammen ' entfernt diesen Effekt.\n\nBetreten eines Bereichs von ' Einäschernde Flammen ' eines anderen Spielercharakters löst eine heftige Explosion aus, die beiden Spielercharakteren 2710541 Feuerschaden zufügt.\n\nVerderbte Flammen\nFügt Gegnern innerhalb von 10 Metern 14 Sek. lang alle 1 Sek. 271054 Schattenflammenschaden zu.\n\nBetreten eines Bereichs von ' Einäschernde Flammen ' entfernt diesen Effekt.\n\nBetreten eines Bereichs von ' Verderbte Flammen ' eines anderen Spielercharakters löst eine heftige Explosion aus, die beiden Spielercharakteren 2710541 Schattenflammenschaden zufügt." }
entries[409648] = { ["name"] = "Zwillingsflammen", ["text"] = "100 Meter Reichweite\nSofort\nHüllt Gegner in ' Einäschernde Flammen ' oder ' Verderbte Flammen '.\n\nEinäschernde Flammen\nFügt Gegnern innerhalb von 10 Metern 14 Sek. lang alle 1 Sek. 271054 Feuerschaden zu.\n\nBetreten eines Bereichs von ' Verderbte Flammen ' entfernt diesen Effekt.\n\nBetreten eines Bereichs von ' Einäschernde Flammen ' eines anderen Spielercharakters löst eine heftige Explosion aus, die beiden Spielercharakteren 2710541 Feuerschaden zufügt.\n\nVerderbte Flammen\nFügt Gegnern innerhalb von 10 Metern 14 Sek. lang alle 1 Sek. 271054 Schattenflammenschaden zu.\n\nBetreten eines Bereichs von ' Einäschernde Flammen ' entfernt diesen Effekt.\n\nBetreten eines Bereichs von ' Verderbte Flammen ' eines anderen Spielercharakters löst eine heftige Explosion aus, die beiden Spielercharakteren 2710541 Schattenflammenschaden zufügt." }
