entries[409745] = { ["name"] = "Schleifender Gewittersturm", ["text"] = "Unbegrenzte Reichweite\nWirken in 2.7 sek.\nFyrakks Anhänger ruft ein einen düsteren Flammenschwall herbei, der allen Spielercharakteren 20 Schattenflammenschaden zufügt und sie zurückstößt. Die sengende Welle verursacht zusätzlich 15 Sek. lang alle 1 Sek. weitere 3 Schattenflammenschaden." }
