entries[409837] = { ["name"] = "Vorspulen", ["text"] = "Sofort\nPasst den Zeitstrom für Spielercharaktere an und erhöht ihre Geschwindigkeit erheblich, was es ihnen ermöglicht, Angriffen von Gegnern auszuweichen." }
