entries[409846] = { ["name"] = "Stein werfen", ["text"] = "20 Meter Reichweite\nSofort 1.5 sek. Abklingzeit\nWirft einen Stein an einen Ort. Fügt Gegnern innerhalb von 10 Metern um den Einschlagsort 25 körperlichen Schaden zu.\n\nSteinbrocken haben viele Verwendungszwecke, Ihr könnt damit auch etwas blockieren!" }
