entries[410230] = { ["name"] = "Wallender Sporenmantel", ["text"] = "Bei über 70% Gesundheit erhaltet Ihr 7 Vielseitigkeit und werdet alle 5 Sek. um 53 Gesundheit geheilt.\n\nBei unter 30% Gesundheit dehnen sich die symbiotischen Sporen in Eurem Umhang aus und gewähren Euch einen Schild, der 10 Sek. lang 1275 Schaden absorbiert. Dieser Effekt kann nur einmal alle 2 Min. auftreten." }
entries[410231] = { ["name"] = "Wallender Sporenmantel", ["text"] = "Sofort\nBei über 70% Gesundheit erhaltet Ihr 7 Vielseitigkeit und werdet alle 5 Sek. um 53 Gesundheit geheilt.\n\nBei unter 30% Gesundheit dehnen sich die symbiotischen Sporen in Eurem Umhang aus und gewähren Euch einen Schild, der 10 Sek. lang 1275 Schaden absorbiert. Dieser Effekt kann nur einmal alle 2 Min. auftreten." }
entries[410232] = { ["name"] = "Wallender Sporenmantel", ["text"] = "Sofort\nSolange Eure Gesundheit über 50% liegt, werdet Ihr als 'Würdig' erachtet, was Euren höchsten Sekundärwert um 66 erhöht. Wenn Eure Gesundheit unter 50% liegt, werdet Ihr als 'Unwürdig' erachtet, was Euren höchsten Sekundärwert um 66 verringert." }
entries[410233] = { ["name"] = "Wallender Sporenmantel", ["text"] = "100 Meter Reichweite\nSofort\nSymbiotische Sporen können Euch nicht beistehen." }
