entries[410243] = { ["name"] = "Abyssischer Atem", ["text"] = "300 Meter Reichweite\nSofort\nSarkareth holt tief Luft und fliegt zu einer neuen Position, wobei er 429755 Schattenschaden in einer Linie verursacht und Spielercharaktere zurückstößt." }
