entries[410245] = { ["name"] = "Schwurstein anzapfen", ["text"] = "Sofort\nWenn Tyrs Energie aufgebraucht ist, entzieht er dem ewigen Schwurstein Kraft und schützt sich mit ' Strahlende Barriere '.\n\nDieser Akt destabilisiert den Schwurstein, wodurch er ' Temporalessenz ' freisetzt." }
entries[410246] = { ["name"] = "Zerschmetterter Geist", ["text"] = "Unbegrenzte Reichweite\nSofort\nDunkle Mächte übernehmen die Kontrolle über den zerschmetterten Geist eines Spielercharakters, was seine Gesundheit zusätzlich um 200% und seinen verursachten Schaden um 50% erhöht." }
entries[410247] = { ["name"] = "Hallendes Geheule", ["text"] = "Sofort\nWenn ' Tyrannisierendes Heulen ' von einem Spielercharakter entfernt wird, bricht hallende Dunkelheit hervor und fügt allen Spielercharakteren 28650 Schattenschaden sowie 4 Sek. lang zusätzlich alle 1 Sek. 7640 Schattenschaden zu. Dieser Effekt ist stapelbar." }
entries[410248] = { ["name"] = "Meisterschäfer", ["text"] = "Während ein gegnerischer Spielercharakter von Eurer 'Verwandlung' oder 'Massenverwandlung' betroffen ist, ist Eure Bewegungsgeschwindigkeit um 25% und Eure Vielseitigkeit um 12% erhöht.\n\nZusätzlich werden Gegner durch 'Verwandlung' und 'Massenverwandlung' nicht mehr geheilt.\n(1s Abklingzeit)" }
