entries[410351] = { ["name"] = "Brennender Knüppel", ["text"] = "100 Meter Reichweite\nWirken in 3 sek. 4 sek. Abklingzeit\nKriegsfürst Kagni schmettert seinen gewaltigen Knüppel in Richtung seines aktuellen Ziels, fügt Spielercharakteren innerhalb eines kegelförmigen Bereichs vor sich 477506 körperlichen Schaden zu und erhöht ihren erlittenen körperlichen Schaden 45 Sek. lang um 15%. Dieser Effekt ist stapelbar.\n\nDie Wucht des Einschlags lässt alle Spielercharaktere in Flammen aufgehen, was Zielen innerhalb von 6 Metern um ihren Standort 238753 Feuerschaden zufügt." }
entries[410352] = { ["name"] = "Zeit dehnen", ["text"] = "Wenn Ihr während [ Atem der Äonen : 'Atem der Äonen' / 'Tiefer Atem'] fliegt, wird Euch 50% des Schadens, den Ihr erleiden würdet, stattdessen im Verlauf von 10 Sek. zugefügt." }
entries[410353] = { ["name"] = "Brennender Knüppel", ["text"] = "Unbegrenzte Reichweite\nSofort\nKriegsfürst Kagni schmettert seinen gewaltigen Knüppel in Richtung seines aktuellen Ziels, fügt Spielercharakteren innerhalb eines kegelförmigen Bereichs vor sich 477506 körperlichen Schaden zu und erhöht ihren erlittenen körperlichen Schaden 45 Sek. lang um 15%. Dieser Effekt ist stapelbar.\n\nDie Wucht des Einschlags lässt alle Spielercharaktere in Flammen aufgehen, was Zielen innerhalb von 6 Metern um ihren Standort 238753 Feuerschaden zufügt." }
entries[410354] = { ["name"] = "Wilde Einstimmung", ["text"] = "Nach erfolgreichen Einsätzen von 'Wirbelsturm' nehmt Ihr automatisch die Katzengestalt an und Euer nächster Einsatz von 'Wilder Biss', 'Zerfetzen' oder 'Zerfleddern' innerhalb von 5 Sek. löst außerdem 'Wilde Raserei' aus." }
entries[410355] = { ["name"] = "Zeit dehnen", ["text"] = "2% von Grundmana\nSofort\nWenn Ihr während [ Atem der Äonen : 'Atem der Äonen' / 'Tiefer Atem'] fliegt, wird Euch 50% des Schadens, den Ihr erleiden würdet, stattdessen im Verlauf von 10 Sek. zugefügt." }
entries[410356] = { ["name"] = "Zeitlinienzurückweisung", ["text"] = "Sofort 15 sek. Abklingzeit\nWeist einen Bereich der Zeitlinie um den Zaubernden zurück und entfernt 6 Sek. lang alle 1 Sek. eine Anwendung von ' Schmetternder Ansturm ' von Verbündeten innerhalb von 7 Metern." }
entries[410357] = { ["name"] = "Geronnene Masse", ["text"] = "100 Meter Reichweite\nSofort\nFügt einem Gegner beim Einschlag 45554 Naturschaden und zusätzlich 15 Sek. lang alle 5.2 Sek. 0 Naturschaden zu.\n\nVerspritzt außerdem eine Schleimsalve, die im Effektbereich 238753 Naturschaden verursacht." }
entries[410358] = { ["name"] = "Antimagische Hülle", ["text"] = "40 Meter Reichweite\nSofort 1 min Abklingzeit\nUmgibt Euer Ziel 5 Sek. lang mit einer antimagischen Hülle, die bis zu [Gesamtgesundheit * 30 / 100 * (1 + Vielseitigkeit) * 1 * 1 ] Magieschaden absorbiert und schädliche magische Effekte abwehrt. Absorbierter Schaden erzeugt Runenmacht." }
