entries[410502] = { ["name"] = "Weyrnstein verschenken", ["text"] = "100 Meter Reichweite\nSofort\nBeschwört zwei Weyrnsteine, einen für Euer verbündetes Ziel und einen für Euch selbst. Nur ein Verbündeter kann Euren Weyrnstein zur gleichen Zeit tragen.\n\nEin Weyrnstein kann von seinem Träger aktiviert werden, um ihn zum Ort des anderen Weyrnsteins zu teleportieren, wenn dieser sich in einem Umkreis von 100 Metern aufhält." }
