entries[410507] = { ["name"] = "Segen der Winterpelze", ["text"] = "100 Meter Reichweite\nSofort\nCa. 15 Procs pro Minute\nBeschwört ein Winterpelztotem am Zielort, das 20 Sek. lang anhält. Gruppenmitglieder innerhalb von 10 Metern haben eine hohe Chance, mit schädlichen Zaubern und Fähigkeiten 695 zusätzlichen Naturschaden zu verursachen.\n\nDer zusätzliche Schaden erhöht sich, wenn der betroffene Verbündete ein Furbolg ist.\n(500ms Abklingzeit)" }
entries[410508] = { ["name"] = "Weyrnstein verschenken", ["text"] = "100 Meter Reichweite\nSofort\nBeschwört zwei Weyrnsteine, einen für Euer verbündetes Ziel und einen für Euch selbst. Nur ein Verbündeter kann Euren Weyrnstein zur gleichen Zeit tragen.\n\nEin Weyrnstein kann von seinem Träger aktiviert werden, um ihn zum Ort des anderen Weyrnsteins zu teleportieren, wenn dieser sich in einem Umkreis von 100 Metern aufhält." }
