entries[410511] = { ["name"] = "Unerbittliche Qual", ["text"] = "Unbegrenzte Reichweite\nSofort\nWenn ein Strahl der Pein beim nächsten Wirken noch aktiv ist, erhält er ' Unerbittliche Qual '. Der Strahl wird schneller und beginnt, siedende Wut zu verströmen, die allen Spielercharakteren alle 2 Sek. 47751 Schattenflammenschaden zufügt und mit jedem Impuls 50% Intensität hinzugewinnt." }
entries[410513] = { ["name"] = "Weyrnstein verschenken", ["text"] = "Beschwört zwei Weyrnsteine, einen für Euer verbündetes Ziel und einen für Euch selbst. Nur ein Verbündeter kann Euren Weyrnstein zur gleichen Zeit tragen.\n\nEin Weyrnstein kann von seinem Träger aktiviert werden, um ihn zum Ort des anderen Weyrnsteins zu teleportieren, wenn dieser sich in einem Umkreis von 100 Metern aufhält." }
entries[410515] = { ["name"] = "Unerbittliche Qual", ["text"] = "Unbegrenzte Reichweite\nSofort\nWenn ein Strahl der Pein beim nächsten Wirken noch aktiv ist, erhält er ' Unerbittliche Qual '. Der Strahl wird schneller und beginnt, siedende Wut zu verströmen, die allen Spielercharakteren alle 2 Sek. 47751 Schattenflammenschaden zufügt und mit jedem Impuls 50% Intensität hinzugewinnt." }
entries[410516] = { ["name"] = "Katastrophales Schmettern", ["text"] = "Unbegrenzte Reichweite\nWirken in 4.3 sek.\nBei Erreichen von 100 Energie sendet Kriegsfürst Kagni eine verheerende Schockwelle zur Tür des Ältesten. Diese verursacht 1910024 körperlichen Schaden, der gleichmäßig auf alle Spielercharaktere auf dem Weg aufgeteilt wird und belegt sie mit ' Geschwächte Lebenskraft '.\n\nKriegsfürst Kagni verbraucht bis zu 100 Energie, reduziert um die Anzahl der getroffenen Spielercharaktere. Wenn Energie verbleibt, löst ' Katastrophales Schmettern ' einen ' Barrierenrückschlag ' aus." }
